// src/data/clubs.js
// 114 clubs across 6 full-size leagues, matching real top-flight counts:
// Premier League 20, La Liga 20, Serie A 20, Bundesliga 18, Ligue 1 18,
// Saudi Pro League 18. Ratings are generated by tier position within
// each league (roughly strongest-to-weakest) so odds stay sensible —
// tweak any club's ratings from the Admin panel.

export const LEAGUES = [
  { id: "premier-league",   name: "Premier League",   flag: "🏴" },
  { id: "la-liga",          name: "La Liga",           flag: "🇪🇸" },
  { id: "serie-a",          name: "Serie A",           flag: "🇮🇹" },
  { id: "bundesliga",       name: "Bundesliga",        flag: "🇩🇪" },
  { id: "ligue-1",          name: "Ligue 1",           flag: "🇫🇷" },
  { id: "saudi-pro-league", name: "Saudi Pro League",  flag: "🇸🇦" },
];

// Ratings scale down gradually from the top of the table to the bottom,
// with a small deterministic wobble so clubs at the same tier aren't
// identical.
function tierRatings(index, total) {
  const t = index / Math.max(1, total - 1); // 0 (top) -> 1 (bottom)
  const overall = Math.round(90 - t * 26);   // 90 down to ~64
  const wobble = (n) => ((index * 7 + n * 13) % 5) - 2; // -2..+2

  return {
    attack:          Math.max(40, overall + wobble(1)),
    midfield:        Math.max(40, overall + wobble(2)),
    defence:         Math.max(40, overall - 1 + wobble(3)),
    goalkeeping:     Math.max(40, overall - 2 + wobble(4)),
    overall,
    form:            Math.max(40, overall - 4 + wobble(5)),
    homeAdvantage:   6 + (index % 4),
    awayPerformance: Math.max(50, overall - 8 + wobble(6)),
  };
}

function makeLeague(leagueId, names) {
  return names.map((name, i) => ({
    id: `${leagueId}-${i}`,
    name,
    leagueId,
    logo: null,
    ratings: tierRatings(i, names.length),
  }));
}

